def is_prime(n):
    """判断一个整数是否为素数。"""
    if not isinstance(n, int):
        raise TypeError("n 必须是整数")
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True
```

